// VectorSearch 组件源码 —— 由 build.mjs 注入运行时字符串后生成 dist/components/index.js
// 占位符（引擎源码与样式的注入点）会被 build.mjs 替换为 JSON 字符串字面量。
import { h } from "preact"

const classNames = (...classes) => classes.filter(Boolean).join(" ")

export const VectorSearch = (userOpts = {}) => {
  const Component = ({ displayClass }) => {
    const placeholder = userOpts.placeholder || "语义搜索…"
    return h("div", { class: classNames(displayClass, "vector-search") }, [
      h("input", {
        class: "search-bar",
        type: "text",
        autocomplete: "off",
        "aria-label": placeholder,
        placeholder,
      }),
      h("div", { class: "vector-results" }),
    ])
  }
  Component.displayName = "VectorSearch"
  Component.afterDOMLoaded = "/* vector-search 浏览器引擎：以字符串内联进站点页面脚本运行。\n * 依赖仅：fetch（服务端检索 API）。\n * 架构（2026-09-22 用户要求）：检索改在服务器端执行（vector_tool/search_server.py），\n *   客户端不再下载 ~70MB 模型/pack/wasm，也不再本地推理；本引擎只负责\n *   UI（输入防抖 → POST /api/search → 渲染结果卡）+ 移动端 TOC 置顶补丁。\n */\n(() => {\n  const TOP_K = 8;\n\n  // ---------- API ----------\n  const API_BASE = (() => {\n    const base = (typeof document !== \"undefined\" &&\n      document.body?.dataset?.basepath) || \"\";\n    return base + \"/api/search\";\n  })();\n  const API_SUGGEST = (() => {\n    const base = (typeof document !== \"undefined\" &&\n      document.body?.dataset?.basepath) || \"\";\n    return base + \"/api/suggest?q=\";\n  })();\n\n  // ---------- doc_path -> 站点 URL（对齐 slugifyFilePath/simplifySlug） ----------\n  function slugifyPath(s) {\n    return s.split(\"/\")\n      .map((seg) => seg.replace(/\\s/g, \"-\").replace(/&/g, \"-and-\")\n        .replace(/%/g, \"-percent\").replace(/\\?/g, \"\").replace(/#/g, \"\")\n        .replace(/[<>:\"|*]/g, \"\").toLowerCase())\n      .join(\"/\").replace(/\\/$/, \"\");\n  }\n\n  function docPathToUrl(p) {\n    let fp = p.replace(/^\\//, \"\").replace(/\\.(md|html)$/i, \"\");\n    let slug = slugifyPath(fp);\n    const segs = slug.split(\"/\");\n    if (segs.length >= 2 && segs[segs.length - 1] === segs[segs.length - 2]) {\n      segs[segs.length - 1] = \"index\";\n      slug = segs.join(\"/\");\n    }\n    if (slug === \"index\") slug = \"\";\n    else if (slug.endsWith(\"/index\")) slug = slug.slice(0, -\"index\".length);\n    else if (slug.endsWith(\"index\")) slug = slug.slice(0, -\"index\".length);\n    const base = document.body?.dataset?.basepath || \"\";\n    return base + \"/\" + slug;\n  }\n\n  // ---------- 搜索历史（localStorage） ----------\n  const HIST_KEY = \"vs-search-history\";\n  const HIST_MAX = 10;\n  function getHist() {\n    try { const h = JSON.parse(localStorage.getItem(HIST_KEY) || \"[]\"); return Array.isArray(h) ? h : []; }\n    catch (e) { return []; }\n  }\n  function addHist(q) {\n    try {\n      const h = getHist().filter((x) => x !== q);\n      h.unshift(q);\n      localStorage.setItem(HIST_KEY, JSON.stringify(h.slice(0, HIST_MAX)));\n    } catch (e) { /* localStorage 不可用时静默 */ }\n  }\n  // 常用词引导（服务端 /api/suggest 空查询返回别名表术语，内存缓存一次）\n  let HOT_CACHE = null;\n  function loadHot(cb) {\n    if (HOT_CACHE) { cb(HOT_CACHE); return; }\n    fetch(API_SUGGEST, { method: \"GET\" })\n      .then((r) => (r.ok ? r.json() : null))\n      .then((j) => { HOT_CACHE = (j && j.suggestions) || []; cb(HOT_CACHE); })\n      .catch(() => { HOT_CACHE = []; cb([]); });\n  }\n  function renderHist(box, input) {\n    const h = getHist();\n    const bind = (sel, fn) => box.querySelectorAll(sel).forEach(fn);\n    const render = (hot) => {\n      if (!h.length && !hot.length) { box.innerHTML = \"\"; return; }\n      const histHtml = h.length\n        ? '<div class=\"vs-history\">最近搜索：' + h.map((x) =>\n            '<button class=\"vs-chip\" type=\"button\" data-q=\"' + esc(x) + '\">' + esc(x) + \"</button>\").join(\"\") +\n          '<button class=\"vs-clear\" type=\"button\" title=\"清除历史\">✕</button></div>'\n        : \"\";\n      const hotHtml = hot.length\n        ? '<div class=\"vs-hot\">常用：' + hot.map((x) =>\n            '<button class=\"vs-chip\" type=\"button\" data-q=\"' + esc(x) + '\">' + esc(x) + \"</button>\").join(\"\") + \"</div>\"\n        : \"\";\n      box.innerHTML = histHtml + hotHtml;\n      bind(\".vs-chip\", (b) => b.addEventListener(\"click\", () => {\n        const q2 = b.dataset.q;\n        input.value = q2;\n        runSearch(q2, box);\n      }));\n      const cl = box.querySelector(\".vs-clear\");\n      if (cl) cl.addEventListener(\"click\", () => {\n        try { localStorage.removeItem(HIST_KEY); } catch (e) {}\n        box.innerHTML = \"\";\n        input.focus();\n        renderHist(box, input);\n      });\n    };\n    // 历史先渲染（即时），常用词到达后合并渲染\n    if (h.length) render([]);\n    loadHot((hot) => { if (!input.value.trim()) render(hot); });\n  }\n\n  // ---------- 检索 ----------\n  let seq = 0;\n  function renderError(box, msg, query) {\n    box.innerHTML = '<div class=\"vs-status vs-error\">检索失败：' + msg +\n      '<button class=\"vs-retry\" type=\"button\">重试</button></div>';\n    const btn = box.querySelector(\".vs-retry\");\n    if (btn) btn.addEventListener(\"click\", () => runSearch(query, box));\n  }\n  function closePanel(input, box) {\n    input.value = \"\";\n    box.innerHTML = \"\";\n    input.blur();\n    document.body.style.removeProperty(\"overflow\");   // 解锁背景滚动\n    document.body.style.removeProperty(\"padding-right\");\n  }\n  function lockScroll() {                             // 面板有内容时锁背景滚动\n    const sw = window.innerWidth - document.documentElement.clientWidth;\n    document.body.style.overflow = \"hidden\";\n    if (sw > 0) document.body.style.paddingRight = sw + \"px\";  // 补滚动条宽度防跳动\n  }\n  async function runSearch(query, box, k) {\n    const mySeq = ++seq;\n    const kk = k || TOP_K;\n    // 「查看更多」（k > TOP_K）时保留面板滚动位置；新查询/输入变化回顶\n    const keepScroll = kk > TOP_K;\n    const prevScroll = box.scrollTop;\n    if (!query || !query.trim()) { renderHist(box, document.querySelector(\".vector-search > .search-bar\")); return; }\n    addHist(query.trim());\n    box.innerHTML = '<div class=\"vs-status\">正在检索…</div>';\n    try {\n      const q2 = query.trim();\n      const [r, sugR] = await Promise.all([\n        fetch(API_BASE, {\n          method: \"POST\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify({ q: q2, k: kk }),\n        }),\n        fetch(API_SUGGEST + encodeURIComponent(q2)).catch(() => null),\n      ]);\n      if (!r.ok) {\n        if (mySeq !== seq) return;\n        renderError(box, \"HTTP \" + r.status, query);\n        return;\n      }\n      const data = await r.json();\n      if (mySeq !== seq) return;\n      const hits = data.results || [];\n      const terms = (data.terms || []).filter((t) => t.length >= 1);\n      // 猜你想搜（suggest 中非当前查询的词）\n      let sug = [];\n      try {\n        if (sugR && sugR.ok) {\n          const sj = await sugR.json();\n          sug = (sj.suggestions || []).filter((s) => s !== q2);\n        }\n      } catch (e) { sug = []; }\n      const sugHtml = !hits.length && sug.length\n        ? '<div class=\"vs-suggest\">猜你想搜：' + sug.slice(0, 5).map((s) =>\n            '<button class=\"vs-chip\" type=\"button\" data-q=\"' + esc(s) + '\">' + esc(s) + \"</button>\").join(\"\") + \"</div>\"\n        : \"\";\n      if (!hits.length) {\n        box.innerHTML = '<div class=\"vs-status\">无结果。试试换个词。</div>' + sugHtml;\n        box.querySelectorAll(\".vs-suggest .vs-chip\").forEach((b) => b.addEventListener(\"click\", () => {\n          const inp = document.querySelector(\".vector-search > .search-bar\");\n          if (inp) { inp.value = b.dataset.q; runSearch(b.dataset.q, box); }\n        }));\n        return;\n      }\n      const hl = (s) => {                       // 查询词高亮（s 已 esc；terms 逐词高亮）\n        let out = s;\n        for (const t of terms) {\n          const qt = esc(t);\n          if (!qt || !out.includes(qt)) continue;\n          out = out.split(qt).join('<mark class=\"vs-hl\">' + qt + \"</mark>\");\n        }\n        return out;\n      };\n      const near = (text, toks, w) => {          // snippet：覆盖最多命中词的最短窗口\n        const lower = text.toLowerCase();\n        const pos = [];\n        for (const t of toks) {                  // 收集所有命中位置（多词多位置）\n          if (!t) continue;\n          const tl = t.toLowerCase();\n          let i = -1;\n          while ((i = lower.indexOf(tl, i + 1)) !== -1) pos.push(i);\n        }\n        if (!pos.length) return text.slice(0, 150);\n        // 暴力枚举起止命中点，选覆盖词数最多、其次最短的窗口\n        let best = null;\n        for (const s of pos) {\n          for (const e of pos) {\n            if (e < s) continue;\n            const covered = pos.filter((p) => p >= s && p <= e).length;\n            if (!best || covered > best.covered ||\n                (covered === best.covered && e - s < best.len)) {\n              best = { s, e, covered, len: e - s };\n            }\n          }\n        }\n        const start = Math.max(0, best.s - w);\n        const end = Math.min(text.length, best.e + w);\n        return (start > 0 ? \"…\" : \"\") + text.slice(start, end) +\n          (end < text.length ? \"…\" : \"\");\n      };\n\n      const html = [];\n      const seen = new Set();\n      for (const h of hits) {\n        if (seen.has(h.doc_path)) continue;      // 双保险：同文档只出一卡\n        seen.add(h.doc_path);\n        const url = docPathToUrl(h.doc_path) +\n          (h.heading ? \"#\" + encodeURIComponent(h.heading) : \"\");   // 锚点直达命中章节\n        // 标题优先文档文件名（短、稳定）；heading 太长时不用\n        const fileTitle = h.doc_path.split(\"/\").pop().replace(/\\.md$/i, \"\")\n          .replace(/^\\d{3}-/, \"\");\n        const title = (h.heading && h.heading.length <= 24) ? h.heading : fileTitle;\n        const raw = (h.text || \"\").replace(/[#>*`\\[\\]!]/g, \"\").replace(/\\s+/g, \" \").trim();\n        const snip = near(raw, terms.length ? terms : [q2], 60);\n        const pct = Math.max(0, Math.min(100, Math.round(h.score * 100)));\n        const whyTxt = h.why === \"path\" ? \"路径命中\" : h.why === \"head\" ? \"标题命中\"\n          : h.why === \"text\" ? \"正文命中\" : \"\";\n        const whyHtml = whyTxt\n          ? '<span class=\"vs-why\" title=\"词汇加权来源\">' + whyTxt +\n            (h.boost ? \" +\" + h.boost.toFixed(2) : \"\") + \"</span>\"\n          : \"\";\n        html.push(\n          '<a class=\"result-card\" href=\"' + url + '\">' +\n          '<h3 class=\"card-title\">' + hl(esc(title)) + \"</h3>\" +\n          '<p class=\"card-description\">' + hl(esc(snip)) + \"</p>\" +\n          '<p class=\"vs-meta\"><span class=\"vs-bar\"><span class=\"vs-bar-fill\" style=\"width:' + pct + '%\"></span></span>' +\n          whyHtml +\n          esc((h.domain || \"\").replace(/\\.pack$/, \"\")) + \" · \" + esc(h.doc_path) +\n          ' · <span class=\"vs-score\" title=\"向量相似度 ' + h.vec.toFixed(3) +\n          (h.boost ? \" + 词汇加权 \" + h.boost.toFixed(3) : \"\") + \" = \" + h.score.toFixed(3) + '\">' +\n          h.score.toFixed(3) + \"</span></p>\" +\n          (h.extras && h.extras.length\n            ? '<p class=\"vs-sub\">' + h.extras.slice(0, 3).map((x) =>\n                '<a href=\"' + docPathToUrl(h.doc_path) + \"#\" + encodeURIComponent(x[0]) + '\">' +\n                esc(x[0]) + \"</a>\").join(\" · \") +\n              (h.extras.length > 3 ? '<span class=\"vs-sub-more\">+' + (h.extras.length - 3) + \" 节</span>\" : \"\") +\n              \"</p>\"\n            : \"\") +\n          \"</a>\");\n      }\n      if (mySeq !== seq) return;\n      lockScroll();                        // 面板有内容 → 锁背景滚动\n      // URL 同步：搜索词写入 ?q=，可分享链接、SPA 后退/刷新可恢复\n      // （replaceState 不触发 Quartz nav 事件，仅改地址栏）\n      try { history.replaceState(null, \"\", \"?q=\" + encodeURIComponent(q2)); } catch (e) {}\n      const moreHtml = (hits.length >= kk && kk < 30)\n        ? '<button class=\"vs-more\" type=\"button\">查看更多</button>' : \"\";\n      box.innerHTML = sugHtml +\n        '<div class=\"vs-count\"><span class=\"vs-n\">找到 ' + hits.length + ' 条相关结果</span>' +\n        '<button class=\"vs-close\" type=\"button\" title=\"关闭\">✕</button></div>' + html.join(\"\") + moreHtml;\n      if (keepScroll) box.scrollTop = prevScroll;   // 查看更多后不丢阅读位置\n      const mb = box.querySelector(\".vs-more\");\n      if (mb) mb.addEventListener(\"click\", () => runSearch(q2, box, kk + 22));\n      const ic = box.querySelector(\".vs-close\");\n      if (ic) ic.addEventListener(\"click\", () => {\n        const inp = document.querySelector(\".vector-search > .search-bar\");\n        if (inp) closePanel(inp, box);\n      });\n      box.querySelectorAll(\".vs-suggest .vs-chip\").forEach((b) => b.addEventListener(\"click\", () => {\n        const q2b = b.dataset.q;\n        const inp = document.querySelector(\".vector-search > .search-bar\");\n        if (inp) { inp.value = q2b; runSearch(q2b, box); }\n      }));\n    } catch (e) {\n      if (mySeq === seq) renderError(box, (e && e.message ? e.message : String(e)), query);\n    }\n  }\n\n  const esc = (s) => String(s).replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\")\n    .replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\");\n\n  // ---------- 移动端 TOC 置顶（站点级补丁） ----------\n  // Quartz 在 <1200px 下 `.sidebar.right>.toc{display:none}` 隐藏目录，且右栏被\n  // 排在正文之后。此处把 TOC 节点搬进正文顶部的 <details> 折叠块（桌面自动还原）。\n  const tocWide = window.matchMedia(\"(min-width: 1200px)\");\n  const TOC_OPEN_KEY = \"vs-toc-open\";\n  function tocOpenState() {\n    try { return localStorage.getItem(TOC_OPEN_KEY) !== \"0\"; }\n    catch (e) { return true; }               // 默认展开\n  }\n  function placeToc() {\n    const article = document.querySelector(\".center article\") || document.querySelector(\"article\");\n    if (!article) return;\n    const moved = document.querySelector(\".vs-mobile-toc\");\n    const toc = (moved && moved.querySelector(\".toc\")) ||\n      document.querySelector(\".sidebar.right > .toc\");\n    if (!toc || !toc.querySelector(\"a\")) return;  // 无标题的笔记不显示空目录框\n    if (!tocWide.matches) {\n      if (moved) return;\n      const wrap = document.createElement(\"details\");\n      wrap.className = \"vs-mobile-toc\";\n      wrap.open = tocOpenState();            // 记住上次展开/收起\n      const sum = document.createElement(\"summary\");\n      sum.textContent = \"目录\";\n      wrap.appendChild(sum);\n      wrap.appendChild(toc);\n      wrap.addEventListener(\"toggle\", () => {\n        try { localStorage.setItem(TOC_OPEN_KEY, wrap.open ? \"1\" : \"0\"); } catch (e) {}\n      });\n      article.insertBefore(wrap, article.firstChild);\n    } else if (moved) {\n      const sb = document.querySelector(\".sidebar.right\");\n      const graph = sb && sb.querySelector(\".graph\");\n      if (graph) graph.after(toc);\n      else if (sb) sb.appendChild(toc);\n      moved.remove();\n    }\n  }\n  if (tocWide.addEventListener) tocWide.addEventListener(\"change\", placeToc);\n  else if (tocWide.addListener) tocWide.addListener(placeToc);\n\n  // ---------- UI 挂载 ----------\n  function mount() {\n    document.querySelectorAll(\".vector-search\").forEach((root) => {\n      const input = root.querySelector(\".search-bar\");\n      const box = root.querySelector(\".vector-results\");\n      if (!input || !box) return;\n      // 按 input 元素判断是否已绑定：Quartz 二次渲染会替换 input 节点，\n      // 若用 root 级标记则新 input 永不绑定（输入不搜索、?q= 直达失效）\n      if (input.dataset.vsBound) return;\n      input.dataset.vsBound = \"1\";\n      // 输入框清空按钮（✕，有内容时显示）——先清掉可能残留的旧节点\n      const stale = root.querySelector(\".vs-clear-input\");\n      if (stale) stale.remove();\n      const clearBtn = document.createElement(\"button\");\n      clearBtn.type = \"button\";\n      clearBtn.className = \"vs-clear-input\";\n      clearBtn.title = \"清空\";\n      clearBtn.textContent = \"✕\";\n      clearBtn.style.display = \"none\";\n      input.parentNode.insertBefore(clearBtn, input.nextSibling);\n      clearBtn.addEventListener(\"click\", () => {\n        input.value = \"\";\n        box.innerHTML = \"\";\n        clearBtn.style.display = \"none\";\n        input.focus();\n        renderHist(box, input);\n      });\n      let timer = null;\n      input.addEventListener(\"input\", () => {\n        clearBtn.style.display = input.value ? \"block\" : \"none\";\n        clearTimeout(timer);\n        timer = setTimeout(() => runSearch(input.value, box), 250);\n      });\n      input.addEventListener(\"keydown\", (e) => {\n        if (e.key === \"Escape\") { closePanel(input, box); return; }\n        const cards = Array.from(box.querySelectorAll(\".result-card\"));\n        if (e.key === \"Enter\") {\n          // IME 组合中（中文输入法选字）不拦截\n          if (e.isComposing || e.keyCode === 229) return;\n          e.preventDefault();\n          let idx = cards.findIndex((c) => c.classList.contains(\"vs-active\"));\n          if (idx < 0) idx = 0;                 // 无选中 → 直达第一个\n          if (cards[idx]) cards[idx].click();\n          return;\n        }\n        if (!cards.length) return;\n        let idx = cards.findIndex((c) => c.classList.contains(\"vs-active\"));\n        if (e.key === \"ArrowDown\") {\n          e.preventDefault();\n          idx = idx < 0 ? 0 : (idx + 1) % cards.length;   // 循环：末尾回到第一个\n          activate(cards, idx);\n        } else if (e.key === \"ArrowUp\") {\n          e.preventDefault();\n          idx = idx < 0 ? cards.length - 1 : (idx - 1 + cards.length) % cards.length; // 循环\n          activate(cards, idx);\n        } else if (e.key === \"Home\") {\n          e.preventDefault();\n          activate(cards, 0);\n        } else if (e.key === \"End\") {\n          e.preventDefault();\n          activate(cards, cards.length - 1);\n        }\n      });\n      function activate(cards, idx) {\n        cards.forEach((c, i) => c.classList.toggle(\"vs-active\", i === idx));\n        cards[idx].scrollIntoView({ block: \"nearest\" });\n      }\n      input.addEventListener(\"focus\", () => {\n        if (!input.value.trim() && !box.querySelector(\".vs-history\")) renderHist(box, input);\n      });\n      // URL 直达：?q=关键词 自动搜索（便于从外部链接分享/跳转）\n      try {\n        const qp = new URLSearchParams(location.search).get(\"q\");\n        if (qp && qp.trim()) {\n          input.value = qp;\n          clearBtn.style.display = \"block\";\n          runSearch(qp, box);\n        }\n      } catch (e) { /* ignore */ }\n    });\n    placeToc();\n  }\n\n  // 点击面板外关闭结果（全屏浮层形态下必须有，模块级只注册一次）\n  document.addEventListener(\"click\", (e) => {\n    document.querySelectorAll(\".vector-search\").forEach((root) => {\n      if (root.contains(e.target)) return;\n      const b = root.querySelector(\".vector-results\");\n      if (b && b.innerHTML) b.innerHTML = \"\";\n    });\n  });\n\n  window.__vectorSearch = { runSearch, mount, state: { ready: true } };\n  if (document.readyState === \"loading\") document.addEventListener(\"DOMContentLoaded\", mount);\n  else mount();\n  document.addEventListener(\"nav\", mount);\n  // 兜底：Quartz 会在 nav/渲染过程中重建导航栏 DOM（input 节点被替换），\n  // 仅靠 DOMContentLoaded/nav 可能绑不上新 input（表现为输入不搜索、?q= 失效）。\n  // 用 MutationObserver 节流（非防抖——页面持续变动时防抖会饿死定时器，\n  // 永远不触发），保证变化后 200ms 内必有一次 mount。\n  try {\n    let moLast = 0;\n    let moTimer = null;\n    const runMount = () => { moLast = Date.now(); mount(); };\n    const mo = new MutationObserver(() => {\n      if (Date.now() - moLast > 200) runMount();\n      else {\n        clearTimeout(moTimer);\n        moTimer = setTimeout(runMount, 200);\n      }\n    });\n    mo.observe(document.body, { childList: true, subtree: true });\n  } catch (e) { /* MutationObserver 不可用时忽略 */ }\n})();\n"
  Component.css = ".vector-search {\n  min-width: fit-content;\n  max-width: 14rem;\n  position: relative;\n}\n.vector-search > input.search-bar {\n  width: 100%;\n  box-sizing: border-box;\n  padding: 0.4em 1.9em 0.4em 0.8em;   /* 右侧留清空按钮位置 */\n  font-family: var(--bodyFont);\n  color: var(--dark);\n  font-size: 1em;\n  border: 1px solid var(--lightgray);\n  border-radius: 6px;\n  background: var(--light);\n}\n.vector-search .vs-clear-input {\n  position: absolute;\n  right: 0.4em;\n  top: 50%;\n  transform: translateY(-50%);\n  width: 1.4em;\n  height: 1.4em;\n  line-height: 1.2em;\n  text-align: center;\n  cursor: pointer;\n  border: none;\n  border-radius: 50%;\n  background: var(--lightgray);\n  color: var(--gray);\n  font-size: 0.8em;\n  padding: 0;\n}\n.vector-search > input.search-bar:focus {\n  outline: none;\n  border-color: var(--tertiary);\n}\n.vector-search > .vector-results:empty {\n  display: none;\n}\n/* 结果面板：与内置搜索（.search-container/.search-space）一致的全屏浮层范式\n   —— 居中 65% 宽（移动端 90%）、12vh 起、带模糊遮罩，而不是贴着输入框的窄下拉。 */\n.vector-search > .vector-results:not(:empty) {\n  position: fixed;\n  top: 12vh;\n  left: 50%;\n  right: auto;\n  transform: translateX(-50%);\n  width: 65%;\n  max-width: none;\n  max-height: 70vh;\n  overflow-y: auto;\n  z-index: calc(var(--search-z-index, 999) + 3);\n  background: var(--light);\n  border: 1px solid var(--lightgray);\n  border-radius: 7px;\n  box-shadow: 0 14px 50px rgba(27, 33, 48, 0.12), 0 10px 30px rgba(27, 33, 48, 0.16);\n}\n/* 暗色模式增强：面板与遮罩明度差小、浅色阴影无效——加深阴影、提亮边框，\n   让浮层轮廓可辨（light 模式下规则不生效，保持原样） */\n:root[saved-theme=\"dark\"] .vector-search > .vector-results:not(:empty) {\n  border-color: var(--gray);\n  box-shadow: 0 14px 50px rgba(0, 0, 0, 0.6), 0 6px 18px rgba(0, 0, 0, 0.5);\n}\n:root[saved-theme=\"dark\"] .vector-search:has(> .vector-results:not(:empty))::before {\n  background: rgba(0, 0, 0, 0.45);\n}\n/* 遮罩：结果面板打开时压暗页面（与内置搜索的 backdrop-filter 一致）\n   pointer-events:none 必需——伪元素属于 .vector-search，会吞掉全屏点击，\n   导致「点面板外关闭」失效且页面链接点不动。 */\n.vector-search:has(> .vector-results:not(:empty))::before {\n  content: \"\";\n  position: fixed;\n  inset: 0;\n  background: rgba(27, 33, 48, 0.12);\n  -webkit-backdrop-filter: blur(4px);\n  backdrop-filter: blur(4px);\n  pointer-events: none;\n  z-index: calc(var(--search-z-index, 999) + 2);\n}\n@media (max-width: 800px) {\n  /* 移动端：结果面板真正全屏（顶部 8vh 留给导航栏输入框），可滚动 */\n  .vector-search > .vector-results:not(:empty) {\n    position: fixed;\n    top: 8vh;\n    left: 0;\n    right: 0;\n    bottom: 0;\n    transform: none;\n    width: 100%;\n    max-width: none;\n    max-height: none;\n    border-radius: 0;\n    border: none;\n    border-top: 1px solid var(--lightgray);\n    /* iPhone 底部 home 指示条遮挡滚动内容 */\n    padding-bottom: env(safe-area-inset-bottom, 0);\n  }\n  /* 全屏时关闭按钮可见（特异性高于基础 display:none，后者在下方定义） */\n  .vector-search .vector-results .vs-close {\n    display: inline-block;\n  }\n  /* 移动端触控目标放大：chips 与结果卡更易点中（≥44px 高度）。\n     特异性必须高于基础规则（.vector-search .vs-chip）——媒体块在源文件中\n     位于基础规则之前，同特异性时后者覆盖前者（同 vs-close 的坑） */\n  .vector-search .vector-results .vs-chip {\n    padding: 0.8em 1em;\n    font-size: 1em;\n  }\n  .vector-search .vector-results .result-card {\n    padding: 0.9em 1em;\n  }\n  .vector-search .vector-results .vs-suggest,\n  .vector-search .vector-results .vs-history,\n  .vector-search .vector-results .vs-hot {\n    gap: 0.6em;\n    padding: 0.6em 1em;\n  }\n}\n/* 结果面板滚动条（细） */\n.vector-search > .vector-results::-webkit-scrollbar {\n  width: 6px;\n}\n.vector-search > .vector-results::-webkit-scrollbar-thumb {\n  background: var(--lightgray);\n  border-radius: 3px;\n}\n/* 关闭按钮：桌面隐藏，移动端显示 */\n.vector-search .vs-close {\n  display: none;\n  margin-left: 0.6em;\n  padding: 0.05em 0.5em;\n  cursor: pointer;\n  border: 1px solid var(--lightgray);\n  border-radius: 5px;\n  background: transparent;\n  color: var(--gray);\n  font-size: 0.9em;\n}\n.vector-search .vs-suggest {\n  padding: 0.4em 0.9em;\n  font-size: 0.85em;\n  color: var(--gray);\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4em;\n  border-bottom: 1px solid var(--lightgray);\n}\n.vector-search .vs-bar {\n  display: inline-block;\n  vertical-align: middle;\n  width: 6em;\n  height: 0.5em;\n  border-radius: 3px;\n  background: var(--lightgray);\n  margin-right: 0.4em;\n  overflow: hidden;\n}\n.vector-search .vs-bar-fill {\n  display: block;\n  height: 100%;\n  background: var(--secondary);\n  border-radius: 3px;\n}\n.vector-search .vs-why {\n  display: inline-block;\n  margin-right: 0.4em;\n  padding: 0 0.4em;\n  font-size: 0.85em;\n  border-radius: 3px;\n  background: var(--lightgray);\n  color: var(--gray);\n  white-space: nowrap;\n}\n.vector-search .vs-hot {\n  padding: 0.4em 0.9em;\n  font-size: 0.85em;\n  color: var(--gray);\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4em;\n  border-bottom: 1px solid var(--lightgray);\n}\n.vector-search .vs-count {\n  padding: 0.2em 0.9em;\n  font-size: 0.85em;\n  color: var(--gray);\n  border-bottom: 1px solid var(--lightgray);\n  display: flex;\n  align-items: center;\n}\n.vector-search .vs-count > span.vs-n {\n  margin-right: auto;\n}\n/* 键盘导航选中态 + hover 过渡 */\n.vector-search .result-card {\n  transition: background 0.12s ease;\n}\n.vector-search .result-card.vs-active {\n  background: var(--lightgray);\n  box-shadow: inset 0 0 0 2px var(--tertiary);\n}\n.vector-search .result-card:hover {\n  background: var(--highlight);\n}\n/* 移动端 TOC 置顶块（节点由引擎 placeToc() 搬入正文顶部） */\n.vs-mobile-toc {\n  margin: 0 0 1.25rem;\n  padding: 0.35rem 0.75rem;\n  border: 1px solid var(--lightgray);\n  border-radius: 6px;\n  background: var(--light);\n}\n.vs-mobile-toc > summary {\n  cursor: pointer;\n  padding: 0.3rem 0;\n  font-weight: 600;\n  color: var(--dark);\n}\n.vs-mobile-toc .toc {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n}\n.vs-mobile-toc .toc-content {\n  max-height: 40vh;\n  overflow-y: auto;\n}\n.vs-mobile-toc .toc-header {\n  display: none;\n}\n.vector-search .vs-history {\n  padding: 0.4em 0.9em;\n  font-size: 0.85em;\n  color: var(--gray);\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.4em;\n}\n.vector-search .vs-chip {\n  padding: 0.15em 0.7em;\n  font-size: 0.95em;\n  cursor: pointer;\n  border: 1px solid var(--lightgray);\n  border-radius: 999px;\n  background: transparent;\n  color: inherit;\n  max-width: 13em;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.vector-search .vs-chip:hover {\n  border-color: var(--gray);\n  background: var(--lightgray);\n}\n.vector-search .vs-clear {\n  margin-left: auto;\n  padding: 0.1em 0.5em;\n  cursor: pointer;\n  border: none;\n  background: transparent;\n  color: var(--gray);\n  font-size: 0.9em;\n}\n.vector-search .vs-retry {\n  margin-left: 0.6em;\n  padding: 0.1em 0.7em;\n  font-size: 0.9em;\n  cursor: pointer;\n  border: 1px solid var(--gray);\n  border-radius: 5px;\n  background: transparent;\n  color: inherit;\n}\n.vector-search .vs-more {\n  display: block;\n  width: 100%;\n  padding: 0.5em 0;\n  cursor: pointer;\n  border: none;\n  border-top: 1px solid var(--lightgray);\n  background: transparent;\n  color: var(--secondary);\n  font-size: 0.85em;\n  font-family: var(--bodyFont);\n}\n.vector-search .vs-more:hover {\n  background: var(--lightgray);\n}\n.vector-search .vs-hl {\n  background: rgba(255, 213, 79, .38);\n  border-radius: 3px;\n  padding: 0 1px;\n}\n.vector-search .vs-status {\n  padding: 0.5em 0.9em;\n  color: var(--gray);\n  font-size: 0.9em;\n}\n.vector-search .vs-status.vs-error {\n  color: var(--secondary);\n}\n.vector-search .result-card {\n  display: block;\n  padding: 0.6em 0.9em;\n  text-decoration: none;\n  color: var(--dark);\n  border-bottom: 1px solid var(--lightgray);\n}\n.vector-search .result-card:last-child {\n  border-bottom: none;\n}\n.vector-search .result-card > h3.card-title {\n  margin: 0;\n  font-size: 0.95em;\n  color: var(--secondary);\n}\n.vector-search .result-card > p.card-description {\n  margin: 0.25em 0 0;\n  font-size: 0.85em;\n  color: var(--gray);\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n}\n.vector-search .result-card > p.vs-meta {\n  margin: 0.25em 0 0;\n  font-size: 0.75em;\n  color: var(--tertiary);\n}\n/* 同文档其他命中章节：主卡下的次级链接行 */\n.vector-search .result-card > p.vs-sub {\n  margin: 0.3em 0 0;\n  font-size: 0.78em;\n  color: var(--gray);\n}\n.vector-search .result-card > p.vs-sub a {\n  color: var(--secondary);\n  text-decoration: underline;\n  text-decoration-color: var(--lightgray);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  max-width: 22em;\n  display: inline-block;\n  vertical-align: bottom;\n}\n.vector-search .result-card > p.vs-sub .vs-sub-more {\n  color: var(--gray);\n}\n"
  return Component
}
